globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-27 06:10:45 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"NVIDIAが高性能GPUを「拠点はアメリカにあるが実態は中国企業に支配される子会社」に優先販売していた","url":"https://gigazine.net/news/20261126-nvidia-china-company/","source":"Hatena","published_at":"2026-11-26 18:52","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"NVIDIAの高性能GPU、中国企業支配の子会社へ優先販売の疑い","summary":"NVIDIAの最先端GPUが、アメリカ企業を装いながら実態は中国企業に支配されているパートナー企業を通じて、中国へ輸出されている疑いが浮上しました。CBSの調査により、RiCloud AIやAivresといった企業が、中国人民解放軍や中国企業と深い繋がりを持ちながら、NVIDIAの優先パートナーとしてチップを確保していたことが指摘されています。\n\n輸出規制の網をかいくぐるサプライチェーンの脆弱性が露呈しており、地政学的なリスク管理と輸出管理の厳格化が改めて問われる事態となっています。","importance":10},{"title":"分離推論の KV 転送を push と pull で整理する","url":"https://zenn.dev/tosshi/articles/4e75a768f14852","source":"Zenn","published_at":"2026-11-27 03:29","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"分離推論におけるKVキャッシュ転送：push型とpull型の仕組みと性能差","summary":"PrefillとDecodeを分離する推論構成において、KVキャッシュの転送方式がTTFT（最初のトークン生成時間）に与える影響を解説。vLLMが採用するpush型と従来のpull型を比較し、転送の開始タイミングやメモリ確保の仕組みが性能にどう寄与するかを整理している。\n\npush型はDecode側が事前にメモリを確保し、Prefill側が書き込むことで転送時間を計算に隠蔽できるため、TPOT（トークン生成時間）の短縮に寄与する。一方、pull型は柔軟な負荷分散に向くなど、各方式の特性と実装上のポイントを詳述している。","importance":8},{"title":"AI法改正案の概要 “事業者に安全確保義務 罰則適用も” | NHKニュース","url":"https://news.web.nhk/newsweb/na/nd-20261126de81752","source":"Hatena","published_at":"2026-11-26 18:52","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"政府がAI法改正案の概要を公表、事業者への安全確保義務化","summary":"高性能AIの悪用や暴走への懸念を受け、日本政府はAI法の改正案の概要をまとめました。AI提供事業者を規制対象として指定し、安全性を確保するための措置を講じることを義務付ける内容です。\n\n罰則規定も盛り込まれる見通しであり、AI開発におけるガバナンスとリスク管理が法的に求められるフェーズに入りました。技術の進歩と安全性のバランスをどう取るか、業界全体での対応が急務となっています。","importance":9},{"title":"情報セキュリティ研修を動画でリッチに！AIなら簡単に……出来るわけがなかった","url":"https://zenn.dev/yut_kawabata/articles/4c5c7bbd4893f0","source":"Zenn","published_at":"2026-11-27 03:57","genre":"other","genre_label":"総合・その他IT","headline":"AIで研修動画を効率化する際の落とし穴と人間による舵取りの重要性","summary":"AIを活用してISMS研修動画をリッチに制作しようとした情シス担当者の奮闘記。AIによる効率化は可能だが、中身の設計や現場の文脈を理解したPMとしての人間による舵取りが不可欠であり、AIへの丸投げは教育効果を損なうと警鐘を鳴らす。\n\nDaVinci Resolve、Blender、VOICEPEAK、Claude Codeなどを駆使した「ひとりブラックAI動画スタジオ」の構築事例を紹介。AIは強力な手下だが、結局は泥臭い教材設計が重要であるという教訓を、自身の過労死寸前の経験を交えて解説している。","importance":6},{"title":"パスワード管理アプリ「Bitwarden」がWindows 11/macOSのパスキー機能と統合／OS標準のセキュリティ画面から保存・利用、拡張機能なしでもWebサイトへサインイン","url":"https://forest.watch.impress.co.jp/docs/news/2159319.html","source":"Hatena","published_at":"2026-11-26 16:18","genre":"web","genre_label":"Web開発・言語","headline":"BitwardenがWindows/macOSのパスキー機能と統合し利便性向上","summary":"パスワード管理サービス「Bitwarden」が、Windows 11およびmacOSの標準パスキープロバイダーとして統合されました。これにより、ブラウザ拡張機能がなくても、OS標準のセキュリティ画面からBitwardenの保管庫にあるパスキーを直接作成・利用できるようになります。\n\n今回の統合により、パスキーの保存と同期がよりシームレスになり、ユーザーはOSネイティブな操作感で安全な認証を利用可能です。複数の端末間でのパスキー共有も容易になり、パスワードレス認証の普及を後押しする重要なアップデートといえます。","importance":8},{"title":"自動運転の予測軌跡の可視化動画を誰でも高速に作れるようにする","url":"https://zenn.dev/turing_motors/articles/cbf9872ca90166","source":"Zenn","published_at":"2026-11-26 17:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"自動運転の予測軌跡を可視化する動画生成基盤をAWSで自動化","summary":"チューリング社は、自動運転モデルが予測した走行軌跡を映像に重ねる動画生成プロセスを、AWS Step FunctionsとBatchを活用して自動化しました。従来は手作業やGPU環境の制約で一部のエンジニアしか行えなかった動画生成を、社内ビューアからのリクエストでSlackに通知する仕組みへと刷新しました。\n\nこの改善により、データセット作成のボトルネックを解消し、生成時間を大幅に短縮しました。また、コーディングエージェントを活用した並列処理の最適化により、開発効率と検証スピードが向上しています。自動運転開発における「介入」の振り返りや広報活動を加速させる好例です。","importance":6},{"title":"SSDでGPUメモリをペタバイト級に拡張、キオクシアとNVIDIAがAI向けの実証","url":"https://pc.watch.impress.co.jp/docs/news/2159567.html","source":"Hatena","published_at":"2026-11-26 19:21","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"キオクシアとNVIDIA、SSDでGPUメモリをペタバイト級に拡張","summary":"キオクシアとNVIDIAは、SSDを活用してGPUメモリの実効容量をペタバイト規模まで拡張するAI向けの実証実験を開始しました。HBMの容量不足を補うため、NVMe SSDとソフトウェアライブラリ「SCADA」を組み合わせ、大規模なベクトルデータベースやグラフニューラルネットワークの処理効率化を目指します。\n\nGB200 NVL72システムを用い、システム全体で約1.1PBの拡張容量を確保するこの取り組みは、AIモデルの巨大化に伴うメモリ制約をストレージ階層で解決する重要な技術的アプローチです。","importance":9},{"title":"「Windows Update」後にPCが起動しない！ 古いDVD書き込み用ドライバーが関係？／初期化せずに復旧できた事例が「X」（Twitter）で報告される【やじうまの杜】","url":"https://forest.watch.impress.co.jp/docs/serial/yajiuma/2159318.html","source":"Hatena","published_at":"2026-11-26 15:17","genre":"other","genre_label":"総合・その他IT","headline":"Windows Update後の起動不可問題、古いDVDドライバーが原因の可能性","summary":"Windows 11のアップデート後にPCが起動しなくなる事例が報告されています。原因は、2018年前後のPCに搭載されている古いDVD書き込み用ドライバー「PxHlpa64.sys」と、Windowsの「メモリ整合性」保護機能との互換性問題である可能性が高いとされています。\n\nトラブルが発生した際は、初期化を行う前にスタートアップ修復を試すか、問題のドライバーを無効化することで復旧できる場合があります。古いソフトウェアやドライバーが最新のOSセキュリティ機能と衝突するケースは今後も増える可能性があるため、注意が必要です。","importance":6},{"title":"【Claude Code】鹿野さんが実践するエンジニアの日常業務を爆速にする最新推しツール 大公開","url":"https://speakerdeck.com/tonkotsuboy_com/index-1f2ed0d2-597d-459d-abf2-db8db109c5d6","source":"Hatena","published_at":"2026-11-26 21:31","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"エンジニアの日常業務を爆速化するClaude Code活用術","summary":"エンジニアの業務フローを爆速化するための最新ツールと活用法を公開。仕様策定から実装、動作確認、レビューに至るまで、Claude CodeやArtifact、各種自作スキルを組み合わせた効率化手法を提示している。\n\n特にClaude Artifactを開発ポータルとして活用し、ドキュメントや議論結果、動作確認レポートを一元管理する手法が特徴的。AIを単なるコード生成ツールとしてではなく、プロジェクト全体の進行管理やナレッジ共有のハブとして活用する実践的なアプローチを解説している。","importance":9},{"title":"理解をあきらめないAI駆動開発 ——開発の流れに「理解の工程」を織り込む6つの実践｜株式会社アシュアード","url":"https://note.com/assuredjp/n/n6ec5f6544e0c","source":"Hatena","published_at":"2026-11-26 15:59","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI駆動開発で認知負債を防ぐ「理解の工程」を織り込む重要性","summary":"生成AIの普及によりコード生成速度が飛躍的に向上する一方、開発者がコードの設計意図を理解できない「認知負債」が蓄積する課題が浮き彫りになっています。Assured社のエンジニアリングマネージャーは、AI時代の開発において「なぜその設計なのか」を自分の言葉で説明できる「理解」の重要性を説いています。\n\nAIに依存しすぎると、異常時の対応や持続的な改善が困難になります。開発プロセスの中に「理解の工程」を意識的に組み込み、AIの生産性と人間の理解力を両立させることが、長期的な開発速度を維持するための鍵となります。","importance":9},{"title":"Jev で実現する Generative UI","url":"https://speakerdeck.com/azukiazusa1/slide-efc59f7e-336f-4e6c-8919-27211ebc3d07","source":"Hatena","published_at":"2026-11-26 21:42","genre":"web","genre_label":"Web開発・言語","headline":"Generative UIの実現に向けたJevの活用とデザインシステム連携","summary":"AIが文章だけでなくUIを生成して返す「Generative UI」の概念と、その実装における課題を解説。既存のデザインシステムと整合性を保ちつつ、AIにコンポーネントを生成させるための手法としてJevの活用事例を紹介している。\n\nLLMにコンポーネントの定義と出力形式のルールをプロンプトで渡し、検証を経て描画する仕組みを詳述。プロダクトの品質を維持しながら、AIが文脈に応じて適切なUIを動的に生成するためのノウハウを共有している。","importance":7},{"title":"【重要】「ASOBI STORE(電子書籍)」サービス終了のお知らせ","url":"https://shop.asobistore.jp/news/324/","source":"Hatena","published_at":"2026-11-26 17:22","genre":"other","genre_label":"総合・その他IT","headline":"ASOBI STORE(電子書籍)がPHP脆弱性対応困難でサービス終了","summary":"ASOBI STOREの電子書籍サービスが、使用しているプログラム言語「PHP」の脆弱性対応が困難であることを理由にサービス終了を発表しました。既存のシステム環境ではセキュリティ要件を満たす改修ができないという判断です。\n\nレガシーなシステム環境における脆弱性対応の限界と、それに伴うサービス継続の難しさを象徴する事例です。技術的負債の解消がいかにビジネス継続性に直結するかを示しています。","importance":5},{"title":"自作VMのボットが戦う、Raspberry Pi Zero 2 Wのペイント合戦専用機を作りました","url":"https://zenn.dev/pcfan/articles/a5455f166e02c3","source":"Zenn","published_at":"2026-11-26 13:52","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Raspberry Pi Zero 2 Wで動く自作VMペイント合戦機","summary":"Raspberry Pi Zero 2 Wを活用し、自作の仮想マシン（VM）上で動作するボット同士が盤面を塗り合う「ペイント合戦」専用機を開発した事例。GUI環境を排した軽量な構成で、C言語によるゲームホストとボットの対戦環境を構築している。\n\nボットのプログラムはMacで作成し、実機に持ち寄って対戦させる仕組み。応答のタイムアウトやエラーを可視化する管理機能も実装されており、限られたリソースの中でいかに効率的にプログラムを動かし、観戦を楽しむかというハードウェアとソフトウェアの工夫が詰まった個人開発プロジェクトである。","importance":5},{"title":"1Passwordへの不正アクセスについてまとめてみた - piyolog","url":"https://piyolog.hatenadiary.jp/entry/2026/11/26/153937","source":"Hatena","published_at":"2026-11-26 15:51","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"1Password従業員のGitHubアカウント経由で顧客情報が一部流出","summary":"1Passwordは、従業員のGitHubアカウントが不正アクセスを受け、バックエンドシステムから一部の顧客アカウント情報が取得されたと公表しました。攻撃者はソースコードに悪意あるコードを挿入し、顧客の管理データをダウンロードしました。\n\n流出したのはアカウント識別子やSRPパラメータなどの非秘密情報であり、保管庫のマスターパスワードや保存されたパスワードは無事であると報告されています。1Passwordは即座に侵害されたトークンの失効やシステムの復元を行い、セキュリティ専門家の支援を受けて調査を継続しています。","importance":9},{"title":"GPT-6.2 Astraが歴史学者もわからなかった「1808年に描かれた北米旅行のスケッチブック」の作者を22分で特定","url":"https://gigazine.net/news/20261126-gpt-62-astra-solves-a-historical-mystery/","source":"Hatena","published_at":"2026-11-26 20:08","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"GPT-6.2 Astraが歴史学の難問を22分で解決","summary":"OpenAIの「GPT-6.2 Astra」が、歴史学者でも長年特定できなかった1808年のスケッチブックの作者を、わずか22分で特定しました。AIは画像データとわずかな背景情報から、フランスの小貴族であるシャボー子爵を候補として提示し、その後の検証で筆跡や旅行時期が一致することが判明しました。\n\n数学のような決定論的な分野だけでなく、歴史学のような非決定論的な領域においても、AIが高度な推論と資料調査を組み合わせることで、専門家を凌駕する発見を導き出せる可能性を示しています。","importance":9},{"title":"GinanでGPS衛星の軌道を精密暦に当てはめる：Dockerでの再現手順とつまずいた点","url":"https://zenn.dev/sakanam40/articles/fb89ddb1ab415c","source":"Zenn","published_at":"2026-11-26 22:45","genre":"other","genre_label":"総合・その他IT","headline":"Docker環境でGinanを用いてGPS衛星軌道を精密暦に当てはめる手順","summary":"オープンソースのGNSS解析ツール「Ginan」をDocker上で動かし、GPS衛星軌道を精密暦（SP3）に当てはめる手順を解説。MongoDBの無効化や座標系の設定など、環境構築でつまずきやすいポイントを詳細に記録している。\n\n特に地球固定系での出力設定を忘れると慣性系との間で大きな誤差が生じる点など、実務的な注意点を網羅。設定ファイル（YAML）の修正箇所や、入力データの取得方法、実行時のコマンド構成までをステップバイステップで説明している。","importance":4},{"title":"MetaのAIエージェント「Muse」による買い物をAmazonがブロックしている件について「解除」する方向での提携について協議中との報道","url":"https://gigazine.net/news/20261126-muse-amazon-discuss/","source":"Hatena","published_at":"2026-11-26 19:04","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"MetaのAIエージェント「Muse」とAmazonが提携協議へ","summary":"MetaのAIエージェント「Muse」によるAmazonでの買い物代行をAmazonがブロックしていましたが、両社がブロック解除に向けた協議を行っていることが報じられました。Amazonはプライバシーや広告収益への影響を懸念していましたが、AIショッピングの普及を見据え、検索結果や広告の扱いを焦点に交渉が進んでいます。\n\nAIエージェントがEC市場に与える影響は大きく、2030年までに市場の10〜20%を占める可能性があると予測されています。プラットフォーム間でのAI連携と収益モデルの再構築が今後の鍵となります。","importance":8},{"title":"既存のExcelを自動で編集したい──AIに書かせたOffice ScriptsとCopilot Studioで試してみた","url":"https://zenn.dev/upgradetech/articles/1bed37bcbf0732","source":"Zenn","published_at":"2026-11-26 12:37","genre":"web","genre_label":"Web開発・言語","headline":"Office ScriptsとCopilot StudioによるExcel自動化","summary":"既存の複雑なExcelファイルを、ファイル構造を変えずにCopilot Studioのエージェントから検索・更新する手法を解説。Office Scripts（TypeScript）を活用し、見出しの文字からセル位置を特定するスクリプトを生成・実行する。\n\nAgent Builderを用いてスクリプト生成エージェントを作成し、プロンプトの工夫によってエラーを抑えつつ実用的な自動化を実現。テーブル形式ではない既存の台帳をそのまま操作できるため、業務効率化のハードルを下げることができる。AIを活用したOffice自動化の具体的な実践例である。","importance":7},{"title":"「1Password」のGitHubアカウントに不正アクセス、顧客管理データの一部漏えい。パスワードの「保管庫」は影響なし","url":"https://internet.watch.impress.co.jp/docs/news/2159331.html","source":"Hatena","published_at":"2026-11-26 12:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"1PasswordのGitHubアカウント不正アクセスと影響範囲","summary":"1Passwordの従業員GitHubアカウントが不正アクセスを受け、顧客管理データの一部が流出した事件の概要。パスワードを保存する「保管庫」への影響はないと発表された。\n\n流出したデータには氏名やメールアドレス、内部メタデータなどが含まれるが、アカウントへのサインインを可能にするような機密情報は含まれていない。同社は対策を講じるとともに、フィッシング詐欺への注意を呼びかけている。パスワード管理サービスにおけるセキュリティインシデントの対応事例として、ユーザーへの透明性の高い情報開示が重要視されている。","importance":9},{"title":"AIがゼロから設計した新しいCPU「Frostbite」が従来型CPUの4.59倍の電力効率を示す","url":"https://gigazine.net/news/20261126-frostbite-cpu/","source":"Hatena","published_at":"2026-11-26 14:48","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIが設計した新CPU「Frostbite」が従来比4.59倍の電力効率を実現","summary":"スタートアップのArchitect Labsが、AIを用いてアーキテクチャから設計・検証までを完全自動化した汎用CPU「Frostbite」を発表しました。1990年に提唱された「Interaction Nets」計算モデルを採用し、並列処理を効率化することで、消費電力当たりの性能を従来比で平均4.59倍に高めました。\n\nAIエージェントが複数の改善案を試行し、ワークスティーリングなどの最適化手法を自律的に組み込んだ点が画期的です。今後はFPGAでの実行環境提供や設計データの公開も予定されており、半導体設計の自動化と効率化において大きな転換点となる可能性があります。","importance":9},{"title":"SIG-Indiedev(仮)第二回イベント『インディーゲーム開発者における「デバンキング問題」の実態と対策』録画・議事録非公開のオンラインセッションと情報ご提供のお願い | 国際ゲーム開発者協会日本","url":"https://igda.jp/2026/11/24/17317/","source":"Hatena","published_at":"2026-11-26 17:17","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"インディーゲーム開発者を襲う「デバンキング問題」の実態調査","summary":"Steam等の売上金受け取りにおいて、日本の金融機関から海外送金を拒否される「デバンキング（金融排除）」問題が深刻化しています。IGDA日本は、この問題の構造解明と政策提言に向けた匿名実態調査およびオンラインセッションの開催を発表しました。\n\n銀行側からの理由開示がないまま経営リスクに直面する開発者が増えており、業界全体での情報収集と行政への働きかけが急務となっています。ゲーム業界における金融実務の課題を浮き彫りにする重要な取り組みです。","importance":7},{"title":"型チェックが重かったので、クエリの型推論を手放してみた","url":"https://zenn.dev/dress_code/articles/88b55221eea4e0","source":"Zenn","published_at":"2026-11-26 11:15","genre":"web","genre_label":"Web開発・言語","headline":"TypeScriptの型推論負荷を軽減し型チェックを高速化","summary":"TypeScriptの型チェックが重く、開発環境のメモリを圧迫していた問題を解決した事例。特にORM（Prisma/Kysely）の複雑なクエリの型推論がボトルネックとなっていた。\n\nTypeScriptコンパイラの統計情報（--diagnostics）を活用し、型インスタンス化の回数を計測することで、負荷の高い箇所を特定。該当するクエリの型推論をあえて手放すことで、型チェックの仕事量を削減した。パフォーマンス改善のための計測手法と、トレードオフを受け入れる判断基準が示されており、大規模プロジェクトの型定義に悩むエンジニアに有益である。","importance":7},{"title":"130 万行の PostgreSQL の検索を 54 秒 → 1 秒台に改善した話","url":"https://zenn.dev/91works/articles/f865594062b3e1","source":"Zenn","published_at":"2026-11-26 12:16","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"PostgreSQLの検索パフォーマンスを54秒から1秒へ改善","summary":"130万行のPostgreSQLテーブルにおける検索処理を、3つの原因特定と対策により54秒から1秒台へ劇的に改善した事例。同義語展開の最適化、フレーズ検索のインデックス活用、統計情報の更新が主な改善点である。\n\n特にGINインデックスの特性を理解し、フレーズ判定を効率化するためにクエリを書き換えた手法は実践的。また、自動統計更新の閾値と検索期間の不一致がパフォーマンス低下を招いていた点など、DB運用における典型的な落とし穴と解決策が詳細に解説されている。","importance":9},{"title":"ニューヨーク・タイムズが写真家に「ユーザーにもわからないAI機能があるからPhotoshopをアップデートするな」と警告","url":"https://gigazine.net/news/20261126-nyt-warns-not-update-photoshop-ai-features/","source":"Hatena","published_at":"2026-11-26 22:05","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"NYタイムズがPhotoshop 2027へのアップデートを警告した背景","summary":"ニューヨーク・タイムズが写真家に対し、Photoshop 2027へのアップデートを控えるよう警告。同バージョンに搭載された「ユーザーにもわからない生成AI機能」により、意図せず写真のメタデータにAI生成タグが付与されるリスクを懸念している。\n\n報道機関にとって写真の真実性は信頼の根幹であり、AIによる自動編集が意図せぬ形で適用されることは大きなリスクとなる。AdobeのMCP対応などAI機能の拡充が進む中、クリエイター側がツール選定やアップデート管理に慎重になっている現状を浮き彫りにした。","importance":8},{"title":"Snowflake AIMのデスクトップアプリでTeradataからの移行を検証してみた","url":"https://zenn.dev/snowflakejp/articles/snowflake-aim-app-teradata","source":"Zenn","published_at":"2026-11-26 13:07","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Snowflake AIMによるTeradataからの移行検証","summary":"Snowflake AIM for Data Warehousesアプリを活用し、TeradataからSnowflakeへのデータ基盤移行を検証したレポート。テーブル、ビュー、ストアドプロシージャなど26オブジェクトの移行を、AI支援を含めて短時間で完遂したプロセスを紹介する。\n\n移行作業はGUIベースの対話形式で進められ、接続設定からコード変換、データ検証までを効率化できる。ただし、動的SQLやPERIOD型など一部の変換にはAI Agentによる修正が必要であり、本番環境への適用には慎重なテストが不可欠である。データウェアハウス移行の自動化トレンドを示す事例である。","importance":7},{"title":"ターミナルで日本語の長文が「…」や「→」で切れるのを直す（rich の表と delta の git diff）","url":"https://zenn.dev/no215/articles/terminal-long-text-truncated-rich-delta","source":"Zenn","published_at":"2026-11-27 01:48","genre":"web","genre_label":"Web開発・言語","headline":"ターミナルで日本語長文が省略される問題をrichとdeltaの設定で解決","summary":"ターミナル上でMarkdownの表やgit diffを表示する際、日本語の長文が「…」や「→」で切れてしまう問題の原因と対策を解説。richの表ではoverflow設定が、deltaでは折り返し回数の制限が原因であることを特定した。\n\nrichのTable.add_columnのoverflowを「fold」に差し替える関数をzshrcに設定する方法や、deltaのwrap-max-linesを「unlimited」に変更する設定を紹介。ツールごとの挙動を理解し、設定を微調整することで、ターミナルでの可読性を大幅に向上させる手法を提示している。","importance":5},{"title":"Security Hub の SBOM インベントリと DevOps Agent で、脆弱性の検出から影響範囲の調査までを自動化してみた","url":"https://zenn.dev/aws_japan/articles/securityhub-sbom-devops-agent","source":"Zenn","published_at":"2026-11-26 10:28","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Security HubのSBOMインベントリで脆弱性調査を自動化","summary":"Amazon InspectorとSecurity HubのSBOMインベントリ機能を活用し、脆弱性の検出から影響範囲の調査までを自動化する仕組みを構築した事例。リソース内のパッケージ一覧を組織全体で把握することで、迅速な対応を可能にする。\n\nEventBridgeとLambdaを組み合わせ、脆弱性が検出された際にSBOMインベントリから該当パッケージを含むリソースを自動抽出。DevOps Agentが調査を行い、Slackへ報告するフローを実装した。手動調査の負担を大幅に軽減し、セキュリティ運用の効率化を実現する実践的なアーキテクチャである。","importance":9},{"title":"🧠Work IQ・Fabric IQ・Foundry IQ・Web IQ って何だっけ？ Microsoft IQ の 4 つを 1 本で整理する - Qiita","url":"https://qiita.com/aktsmm/items/1a1ef35ee48d7ef665ba?ocid=AID3062894_TWITTER_oo_spl100011804015917","source":"Hatena","published_at":"2026-11-26 21:15","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Microsoft IQの4要素（Work/Fabric/Foundry/Web）を1本で整理","summary":"Microsoftが提供する「Microsoft IQ」の4つのインテリジェンスレイヤー（Work, Fabric, Foundry, Web）の役割と使い分けを整理。これらはAIエージェントが社内外の文脈を理解するための情報源として機能する。\n\nWork IQは個人の業務データ、Fabric IQは構造化データ、Foundry IQは社内文書、Web IQは外部情報と、扱うデータの種類で明確に分かれている。MCPを共通の接続方式として、各IQをどう使い分けるべきかをアーキテクトの視点で解説している。","importance":8},{"title":"J-REITのNAV1倍割れと金利感応度を全銘柄で調べてみた：関係が見られたのは借入より「利益の薄さ」と「規模」","url":"https://zenn.dev/3110mmn/articles/dabda52a2817a7","source":"Zenn","published_at":"2026-11-26 22:15","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"J-REITのNAV1倍割れ要因：金利感応度より「利益の薄さ」と「規模」が影響","summary":"J-REITの投資口価格がNAV（純資産価値）を下回る要因を全銘柄データで分析。金利上昇への弱さが指摘されるREITだが、今回のデータでは借入比率よりも「利益の薄さ」や「時価総額（規模）」との相関が強いことが判明した。\n\n利益の薄い銘柄ほどP/NAVが低くなる傾向があり、市場が分配金利回りを重視して値付けしていることが背景にあると推察。金利ベータについても、借入の多い銘柄より大型銘柄の方が反応が大きいという興味深い結果を報告している。","importance":6},{"title":"Leanによる定理証明と実行時検証の実装例 〜バッテリーの充電制御〜","url":"https://zenn.dev/quetta_kazunoko/articles/battery-safety-lean","source":"Zenn","published_at":"2026-11-26 18:09","genre":"web","genre_label":"Web開発・言語","headline":"Leanを用いたバッテリー充電制御の定理証明と実行時検証","summary":"Leanを使用して、バッテリーの充電制御モデルに対する定理証明と実行時検証を実装する手法が紹介されました。安全性仕様をProp型として定義し、制御器が常に安全な状態を維持することを数学的に証明するアプローチと、実行時に条件を満たすか判定するアルゴリズムを構築する手法を比較しています。\n\n形式手法を制御システムに適用することで、設計段階での論理的な正当性を保証する重要性が示されています。特に組み込みシステムや安全性が重視される分野での応用が期待されます。","importance":6},{"title":"迷惑メール対策をしているのに、なぜ詐欺メールは届くのか","url":"https://zenn.dev/akagumi/articles/catch-all-phishing-invisible-chars","source":"Zenn","published_at":"2026-11-26 23:08","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"認証をすり抜ける詐欺メールの仕組みと対策ロジックの再構築","summary":"SPF/DKIM/DMARCの認証をパスする詐欺メールがなぜ届くのか、その手口を分析。攻撃者は自前ドメインで正当な認証を設定し、Fromヘッダーの表示名やHTML内の見えない文字、制御文字を用いてフィルターを回避している。\n\n対策として、見えない文字の検出、文字参照の段階的デコード、名乗っているブランドとリンク先ドメインの照合を行う判定ロジックの再構築を提案。単純なキーワード判定では防げない高度な詐欺メールに対し、多角的な検証が必要であることを示している。","importance":7},{"title":"画像生成 Nemotron-Labs-Image-30B-A3BをDatabricks AI Runtime の vLLM で動かしてみた","url":"https://zenn.dev/hiouchiy/articles/5b3ffde8e819e6","source":"Zenn","published_at":"2026-11-26 19:43","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"LLMベースの画像生成モデルをvLLMで高速実行","summary":"NVIDIAの画像生成モデル「Nemotron-Labs-Image-30B-A3B」を、DatabricksのAI Runtime上でvLLMを用いて実行する検証が行われました。このモデルは拡散モデルではなくLLMとして画像をトークン出力する仕組みであり、vLLMの推論エンジンとの相性が非常に良いことが確認されました。\n\nCUDAグラフの活用や、GPUリソースを小さなエンジンに分割して並列処理させることで、生成速度を大幅に向上させています。LLMのアーキテクチャを画像生成に応用する新しいトレンドと、その効率的な運用手法を示す好例です。","importance":8},{"title":"サービスチーム全員で2年半続けているドメインモデリングのリアル / domain-modeling-with-the-whole-service-team","url":"https://speakerdeck.com/kaminashi/domain-modeling-with-the-whole-service-team","source":"Hatena","published_at":"2026-11-26 21:14","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"サービスチーム全員で2年半続けたドメインモデリングの変遷とAI活用","summary":"PdM、PD、エンジニア全員で2年半にわたりドメインモデリングを継続してきたチームの歩みを紹介。当初は職種間の認識合わせに有効だったが、プロダクトの成長に伴い議論がボトルネック化する課題に直面した。\n\nこの経験を踏まえ、全員で理解を深めつつ効率を落とさないための進め方の変遷を解説。さらに、Post AI時代におけるドメインモデリングのあり方として、AIをどのように活用してモデリングを加速させるかという展望を実例を交えて語っている。","importance":6},{"title":"週刊Cloudflare - 2026/11/22週","url":"https://zenn.dev/gemcook/articles/weekly-cloudflare_2026_1115-1121","source":"Zenn","published_at":"2026-11-26 14:00","genre":"web","genre_label":"Web開発・言語","headline":"Cloudflareの最新アップデート情報（2026/11/22週）","summary":"2026年11月15日から21日までのCloudflareのアップデートを網羅的に紹介。主な変更点として、Build Outputのv1形式への対応や、ローカル環境でのArtifactsイベントによるWorkflow起動が可能になった点が挙げられる。\n\nまた、Viteプロジェクトの直接実行サポートや、Wranglerにおける設定ファイル監視の改善、Containerの段階的ロールアウトの最適化など、開発者体験を向上させる機能強化が多数実施されている。Cloudflareエコシステムを利用するエンジニアにとって、開発パイプラインの効率化に直結する重要な更新内容となっている。","importance":6},{"title":"Windows 11が「自動修復」ループで起動しない：BIOSで仮想化を無効にしたら起動した（NEC Mate 2台の記録）","url":"https://zenn.dev/yutakatsuhako/articles/9a7d7d1fde4cf7","source":"Zenn","published_at":"2026-11-26 19:54","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Windows 11の起動ループ、BIOS仮想化設定で解決","summary":"Windows 11の更新後に「自動修復」ループで起動しなくなる事象に対し、BIOS設定で仮想化（Intel VT）を無効にすることで解決した事例が報告されました。これはWindows側がVBS（仮想化ベースのセキュリティ）を有効化した際、BIOS設定との不整合で起動が阻害されたことが原因と推測されます。\n\n高速スタートアップが有効な環境では、更新後の再起動まで問題が顕在化しないケースもあり、トラブルシューティングの難しさが浮き彫りになりました。同様の事象に遭遇した際の有効な回避策として参考になります。","importance":7},{"title":"「知らない〝私〟が血を流し罵倒」中国AI短編ドラマで「顔盗用」急増　俳優は泣き寝入り","url":"https://www.sankei.com/article/20261126-SZTQ2RJW5ZKU3GJ4GQKJAORUPE/","source":"Hatena","published_at":"2026-11-26 17:06","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"中国でAI生成俳優による顔・声の盗用被害が急増し社会問題化","summary":"中国の短編ドラマ市場で、実在の俳優の顔や声を無断で学習・生成した「AI俳優」が勝手に出演するトラブルが多発しています。低コストで大量生産できるAIの利便性が悪用され、被害を受けた俳優はイメージダウンや仕事の喪失に直面していますが、規制が追いつかず泣き寝入りするケースが相次いでいます。\n\nこの問題は、生成AIの技術的進化が個人の肖像権や権利保護の枠組みを大きく超えてしまったことで生じています。中国政府は現在、AIコンテンツの管理強化に乗り出していますが、技術の悪用を防ぐための法整備と倫理的なガイドラインの策定が急務となっています。","importance":8},{"title":"個人の目標設定に悩んでいたら、アジャイルが言葉を定義し直すきっかけをくれた話","url":"https://zenn.dev/yoshipon_tech/articles/a0e13c3dbd2f7d","source":"Zenn","published_at":"2026-11-26 14:35","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"アジャイルの定義を再考し個人の目標設定を「価値」ベースへ転換","summary":"個人の目標設定に悩んでいたエンジニアが、アジャイルの考え方を応用して「価値」を再定義した体験談です。定量的な目標設定が「手段の目的化」に陥っていたことに気づき、スクラムガイドの「なぜ価値があるのか」という視点を取り入れました。\n\n「アウトプット（成果物）」ではなく「アウトカム（効果）」を意識することで、目標設定を自分に合った仕組みへと昇華させています。抽象的な言葉を自分なりに定義し直すアジャイルの思考法は、個人のキャリア開発や自己研鑽においても非常に有効なフレームワークとなり得ます。","importance":6},{"title":"fabric.js v6 で作るペイントツール：標準にない undo/redo と矢印の実装","url":"https://zenn.dev/taylor/articles/2f43a6189e5ddf","source":"Zenn","published_at":"2026-11-26 13:22","genre":"web","genre_label":"Web開発・言語","headline":"fabric.js v6でのundo/redoと矢印描画の実装手法","summary":"fabric.js v6とVue 3を用いたペイントツール開発において、標準機能にはない「undo/redo」と「矢印描画」を自作する方法を解説。状態管理の工夫と図形描画のカスタマイズが鍵となる。\n\nundo/redoはキャンバス全体をJSONで保存・復元する方式を採用し、写真データの重複を防ぐためにID管理を導入。矢印描画はLineクラスを継承し、矢じりを動的に描画するクラスを作成することで、標準のハンドル操作にも対応させた。ライブラリの制限を理解し、独自の拡張を加えるための具体的な実装パターンが示されている。","importance":6},{"title":"みずほ銀行、顧客の管理番号3万件が漏洩　委託先に不正アクセス - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUB266I30W6A121C2000000/","source":"Hatena","published_at":"2026-11-26 17:06","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"みずほ銀行の委託先で不正アクセス、顧客管理番号が最大3万件流出","summary":"みずほ銀行は、メール配信業務を委託しているプレイド社が不正アクセスを受け、顧客の管理番号が最大3万3224件漏洩したと発表しました。現時点で氏名、住所、口座暗証番号などの個人を特定できる情報の流出は確認されていません。\n\n漏洩した管理番号は既に無効化されており、対象顧客への連絡が進められています。近年、サプライチェーン上の委託先を狙ったサイバー攻撃が相次いでおり、金融機関を含む企業には、委託先のセキュリティ管理体制の再点検と、より強固な監視体制の構築が求められています。","importance":7},{"title":"24KBの「LLM専用OS」が登場　全てアセンブリでLinuxを排し、llama.cppより最大54%高速 | テクノエッジ TechnoEdge","url":"https://www.techno-edge.net/article/2026/11/26/5824.html","source":"Hatena","published_at":"2026-11-26 15:02","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"24KBのLLM専用OSが登場、アセンブリ記述で推論速度を大幅向上","summary":"開発者のAlexey Fateev氏が、言語モデル「Qwen3-0.6B」を動かすためだけに設計されたOS「asm-llm-os.elf」を発表しました。LinuxやWindowsを排し、すべてx86-64アセンブリ言語で記述されたOS本体はわずか24KBという超軽量サイズです。\n\nこのOSは、巨大ページ（huge page）の活用により、Linux上のllama.cppと比較して最大54%の高速化を実現しています。ディスク容量0GBの環境でも起動可能で、ブートから推論エンジンまでを極限まで最適化しています。AI推論の実行環境におけるOSレベルの最適化の可能性を示す興味深いプロジェクトです。","importance":8},{"title":"人の判断を切り出すAgent Skillsの設計（v7.0.2）","url":"https://zenn.dev/jayt/articles/agent-skills-judgment-extraction","source":"Zenn","published_at":"2026-11-26 11:05","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Agent Skillsにおける「人の判断」を切り出す設計思想","summary":"AIエージェントの出力が一般論に寄る課題に対し、人の判断を「中核判断」と「一般的な業務知識」に分け、Agent Skillsとして切り出す設計手法を提案。作成者の視点を残しつつ、集合知として共有可能なスキル開発を目指す。\n\nAIに作業を任せきりにせず、人が知見を更新し続けるための仕組みとして、スキルの型や判断ファイルの構成を定義。Claude Codeなどのエージェント環境での活用を想定している。AI時代における「人の価値」をどう定義し、システムに組み込むかという哲学的な設計論である。","importance":6},{"title":"ぼくはnullが嫌いだ","url":"https://zenn.dev/okaponta/articles/ea88f9ed0c5be5","source":"Zenn","published_at":"2026-11-26 10:36","genre":"web","genre_label":"Web開発・言語","headline":"nullの歴史とプログラミングにおける弊害の考察","summary":"プログラミングにおける「null」に対する嫌悪感を起点に、その歴史的背景と技術的な弊害を考察した記事。Tony Hoareによる「10億ドルの過ち」という言葉を引用し、null参照がもたらしたシステム上の脆弱性やエラーについて解説する。\n\nC言語やJava、データベースにおけるNULLの扱いの違いを整理し、なぜnullが直感に反する挙動を生むのかを論じている。nullを避ける設計や、より安全な代替手段を検討する重要性を説いており、コードの可読性と堅牢性を高めたいエンジニアにとって深い洞察が得られる内容となっている。","importance":6},{"title":"電力需要の予測はどれくらい当たる？ ― OCCTO公開データで作る予実パイプライン（BigQuery × dbt × Terraform）","url":"https://zenn.dev/shimodata/articles/kyushu-power-forecast-pipeline","source":"Zenn","published_at":"2026-11-26 16:37","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"BigQueryとdbtで構築する電力需要予測の予実管理データ基盤","summary":"電力広域的運営推進機関（OCCTO）の公開データを用い、電力需要の予測と実績を分析するデータ基盤をGoogle Cloud上に構築した事例です。BigQuery、dbt、Terraformを組み合わせ、毎朝の自動取り込みから品質テストまでをパイプライン化しています。\n\n特に、CSV仕様変更への対応や「いつ時点の予測か」を厳密に管理するテスト設計、冪等性を担保したデータ更新など、データ品質と再現性を重視した設計が特徴です。経営管理の予実分析手法を公開データに応用し、エラー検知やCI/CDを組み込むことで、信頼性の高い分析基盤を実現しています。","importance":7},{"title":"GPU Lambda ② vLLM のモデルはどこに置く？4つの構成で起動時間を比べてみた","url":"https://zenn.dev/nix/articles/1ddfbfbb7e3763","source":"Zenn","published_at":"2026-11-26 13:50","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"vLLMモデル配置場所による起動時間と運用コストの比較","summary":"GPU Lambda環境において、vLLMのモデル重みをどこに配置するのが最適かを4つの構成（/tmp、S3直接読み込み、SOCI付きイメージ、イメージ内同梱）で比較検証。起動時間と運用面でのメリット・デメリットを分析した。\n\n検証の結果、応答速度には大きな差がないものの、起動までの時間や運用コストには明確な違いがあることが判明。特にS3からのストリーミングやイメージへの同梱は、コールドスタートの短縮に寄与する。本番環境での安定運用を目指すエンジニアにとって、モデル管理戦略の参考となる実践的な知見である。","importance":8},{"title":"デジタル庁デザインシステムをどう使うか：導入先に合わせた「ローカルデザインシステム」を作る｜デジタル庁ニュース","url":"https://digital-agency-news.digital.go.jp/articles/2026-11-26","source":"Hatena","published_at":"2026-11-26 19:02","genre":"web","genre_label":"Web開発・言語","headline":"デジタル庁デザインシステムの活用とローカル展開","summary":"デジタル庁が提供する「デジタル庁デザインシステム」を、各導入先のブランドや方針に合わせてカスタマイズする「ローカルデザインシステム」の作成手法が解説されました。同システムは特定のブランドを持たない「プラットフォーム型」であり、デザイントークンを編集することで柔軟な適用が可能です。\n\nアクセシビリティを確保しつつ、各府省や自治体、民間サービスが統一感のあるUIを構築するための指針として、デザインシステムの導入を検討する開発者にとって有益なガイドラインとなっています。","importance":5},{"title":"アディーレ法律事務所、個人情報約1828件漏えい　氏名や問い合わせ内容など……委託先「メール商人」に不正アクセス","url":"https://www.itmedia.co.jp/news/article/2611/26/2000003484/","source":"Hatena","published_at":"2026-11-26 15:21","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"アディーレ法律事務所の委託先で不正アクセス、個人情報約1828件流出","summary":"アディーレ法律事務所は、メール配信サービス「メール商人」への不正アクセスにより、同事務所の問い合わせフォームから連絡した顧客の個人情報約1828件が流出したと発表しました。氏名、電話番号、問い合わせ内容などが含まれています。\n\nクレジットカード情報などは含まれていませんが、委託先を狙った攻撃による被害が相次いでいます。企業は自社システムだけでなく、利用しているSaaSや委託先のセキュリティ対策状況を把握し、多要素認証の導入や不要な個人データの削除など、リスク低減策を講じることが急務となっています。","importance":7},{"title":"TenkaCloudSimulator 開発日記：ChatGPTのDotで開発が自律的に続く仕組みをつくる","url":"https://zenn.dev/bull/articles/tenkacloud-simulator-devlog-20261126","source":"Zenn","published_at":"2026-11-26 12:59","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ChatGPTのDotを活用した自律的な開発運用体制","summary":"クラウドシミュレーター「TenkaCloudSimulator」の開発において、ChatGPTのDotとサブエージェントを組み合わせ、Issueの解決からマージまでを自律的に回す仕組みを構築した事例。トークン制限を回避し、効率的に開発を進めるための工夫が語られている。\n\n開発ルールをYAML形式のAGENTS.mdに集約し、AI同士が自律的にタスクを分担・レビューする体制を構築。人間が指示を出し続ける必要をなくすことで、開発速度を向上させている。AIエージェントを活用した大規模な開発運用フローの構築を目指すエンジニアにとって、非常に示唆に富む内容である。","importance":8},{"title":"「安全な経路」の判定から学ぶ、Unix ソケット経由の Cloud SQL 認証エラー","url":"https://zenn.dev/rescuenow/articles/0e7f5fc4e46be3","source":"Zenn","published_at":"2026-11-26 14:08","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Cloud SQLのUnixソケット認証エラーの原因と解決策","summary":"MySQL 8.4以降の認証プラグイン移行に伴い、Cloud Runの組み込みCloud SQL接続（Unixソケット）で認証エラーが発生する問題について解説。原因はMySQLがUnixソケットを「安全な経路」と見なす一方で、Auth Proxyの既知の不具合により認証プロセスが失敗することにある。\n\n解決策として、Unixソケット接続を避け、サイドカーのAuth Proxy経由でTCP接続を行うか、Cloud SQL言語コネクタを使用することが推奨される。本記事では、Unixソケット、TCP、TLSの接続方式の違いと、MySQLの認証メカニズムを深掘りし、なぜこの構成でエラーが起きるのかを技術的に解明している。","importance":7},{"title":"海外の音楽配信サービス、AI生成楽曲の一律禁止を発表。約2700万曲を削除へ【やじうまWatch】","url":"https://internet.watch.impress.co.jp/docs/yajiuma/2159409.html","source":"Hatena","published_at":"2026-11-26 12:25","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"音楽配信サービスTIDALがAI生成楽曲を全面禁止へ","summary":"音楽配信サービス「TIDAL」が、AI生成楽曲を禁止し、約2700万曲を削除すると発表。配信楽曲の60％を占めるに至ったAI生成コンテンツへの対策として、極めて厳しい措置を講じる。\n\n削除対象の楽曲の多くが再生回数ゼロであることから、サービスへの影響は限定的と見られている。Spotifyなど他社がラベル付けによる共存を図る中、TIDALのこの決断は音楽業界におけるAIコンテンツの扱いに関する議論を加速させる可能性がある。AIと著作権、プラットフォームの責任を問う重要なニュースである。","importance":8},{"title":"【さくらのレンタルサーバ】セキュリティ強化に伴うコンパイル・ビルド関連コマンド等の停止に関するお知らせ | さくらインターネット","url":"https://www.sakura.ad.jp/corporate/information/announcements/2026/11/26/1968226380/","source":"Hatena","published_at":"2026-11-26 14:50","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"さくらのレンタルサーバ、セキュリティ強化でコンパイル関連コマンドを停止","summary":"さくらインターネットは、セキュリティ対策強化の一環として、「さくらのレンタルサーバ」等においてコンパイル・ビルド関連コマンドおよび「crontab」コマンドの利用を停止すると発表しました。適用期間は2026年12月3日から12月10日にかけて順次行われます。\n\n今回の措置は、サーバー上での不正なプログラム実行や攻撃を防ぐためのものです。既存のプログラムには影響ありませんが、今後はサーバー上での新規ビルドや再ビルドができなくなります。ユーザーは開発環境の移行や運用方法の見直しが必要となります。","importance":6}]};
